<template>
  <div class="user-management">
    <h2>卫星地面融合网络社区-用户管理</h2>

    <!-- 用户列表 -->
    <el-card>
      <el-table :data="users" style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="ID" width="60"></el-table-column>
        <el-table-column prop="account" label="账号" width="150"></el-table-column>
        <el-table-column prop="nickname" label="昵称" width="120"></el-table-column>
        <el-table-column prop="email" label="邮箱" width="180"></el-table-column>
        <el-table-column prop="admin" label="角色" width="100">
          <template slot-scope="scope">
            <el-tag :type="scope.row.admin ? 'danger' : 'success'" size="small">
              {{ scope.row.admin ? '管理员' : '普通用户' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="status" label="状态" width="100">
          <template slot-scope="scope">
            <el-tag :type="scope.row.status === 'normal' ? 'success' : 'warning'" size="small">
              {{ scope.row.status === 'normal' ? '正常' : '禁用' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="createDate" label="注册时间" width="160">
          <template slot-scope="scope">
            {{ formatDate(scope.row.createDate) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="200" fixed="right">
          <template slot-scope="scope">
            <el-button v-if="!scope.row.admin" type="text" size="small" @click="setAdmin(scope.row)">设为管理员</el-button>
            <el-button type="text" size="small" @click="editUser(scope.row)">编辑</el-button>
            <el-button v-if="!scope.row.admin" type="text" size="small" class="danger-text" @click="deleteUser(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 编辑用户对话框 -->
    <el-dialog title="编辑用户" :visible.sync="editDialogVisible" width="500px">
      <el-form :model="editForm" label-width="80px">
        <el-form-item label="账号">
          <el-input v-model="editForm.account" disabled></el-input>
        </el-form-item>
        <el-form-item label="昵称">
          <el-input v-model="editForm.nickname"></el-input>
        </el-form-item>
        <el-form-item label="邮箱">
          <el-input v-model="editForm.email"></el-input>
        </el-form-item>
        <el-form-item label="状态">
          <el-select v-model="editForm.status">
            <el-option label="正常" value="normal"></el-option>
            <el-option label="禁用" value="disabled"></el-option>
          </el-select>
        </el-form-item>
      </el-form>
      <span slot="footer">
        <el-button @click="editDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmEdit">保存</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { getUserList, updateUser, deleteUser as deleteUserApi } from '@/api/user'

export default {
  name: 'UserManagement',
  data() {
    return {
      users: [],
      loading: false,
      editDialogVisible: false,
      editForm: {
        id: null,
        account: '',
        nickname: '',
        email: '',
        status: 'normal'
      }
    }
  },
  created() {
    this.loadUsers()
  },
  methods: {
    async loadUsers() {
      this.loading = true
      try {
        const res = await getUserList()
        this.users = res.data || []
      } catch (error) {
        this.$message.error('加载用户列表失败')
      } finally {
        this.loading = false
      }
    },
    editUser(user) {
      this.editForm = {
        id: user.id,
        account: user.account,
        nickname: user.nickname,
        email: user.email,
        status: user.status
      }
      this.editDialogVisible = true
    },
    async confirmEdit() {
      try {
        await updateUser(this.editForm)
        this.$message.success('更新成功')
        this.editDialogVisible = false
        this.loadUsers()
      } catch (error) {
        this.$message.error('更新失败')
      }
    },
    async setAdmin(user) {
      try {
        await this.$confirm(`确定要将用户「${user.nickname}」设为管理员吗？`, '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })

        const updatedUser = { ...user, admin: true }
        await updateUser(updatedUser)
        this.$message.success('设置成功')
        this.loadUsers()
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error('设置失败')
        }
      }
    },
    async deleteUser(user) {
      try {
        await this.$confirm(`确定要删除用户「${user.nickname}」吗？此操作不可恢复。`, '警告', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })

        await deleteUserApi(user.id)
        this.$message.success('删除成功')
        this.loadUsers()
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error('删除失败')
        }
      }
    },
    formatDate(date) {
      if (!date) return '-'
      return date.substring(0, 10)
    }
  }
}
</script>

<style scoped>
.user-management {
  padding: 20px;
}

.user-management h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.danger-text {
  color: #F56C6C;
}

.danger-text:hover {
  color: #f66;
}

/* 手机端适配 */
@media screen and (max-width: 767px) {
  .user-management {
    padding: 10px;
  }

  .user-management h2 {
    font-size: 18px;
    margin-bottom: 15px;
  }

  .el-table {
    font-size: 12px;
  }

  .el-table .cell {
    padding: 8px 4px;
  }
}

/* 平板端适配 */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .user-management {
    padding: 15px;
  }

  .user-management h2 {
    font-size: 20px;
  }

  .el-table {
    font-size: 13px;
  }
}
</style>



